package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.blocks.BlockCanopy;
import com.vandorlabs.canopy.*;
import com.vandorlabs.tiles.TileEntityCanopy;
import java.io.*;
import java.util.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.*;

/** Released analytic motion-interval extrema, before any native worker extraction. */
public final class CanopySweepLegacyOracle {
    private static final BlockPos ROOT=new BlockPos(-17,84,35);
    private static final double[][] INTERVALS={{0,1},{0,.5},{.5,1},{.4375,.5},{1,0},{1,.9375},{0,0}};
    static void check(File file,String expected)throws Exception{java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(BufferedReader reader=java.nio.file.Files.newBufferedReader(file.toPath(),java.nio.charset.StandardCharsets.UTF_8)){for(String line;(line=reader.readLine())!=null;){digest.update(line.getBytes(java.nio.charset.StandardCharsets.UTF_8));digest.update((byte)'\n');}}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(!expected.equals(actual.toString()))throw new AssertionError("Released canopy sweep changed "+actual);}
    public static void main(String[] args)throws Exception{List<BlockCanopy> blocks=CanopyPlacementLegacyOracle.initialize();File file=new File(args[0]);file.getAbsoluteFile().getParentFile().mkdirs();Gson gson=new Gson();int profiles=0,boxes=0;
        try(PrintWriter out=new PrintWriter(file,"UTF-8");PrintWriter inputs=new PrintWriter(new File(file.getParentFile(),"canopy-sweep-inputs-forge.jsonl"),"UTF-8")){for(BlockCanopy block:blocks)for(int profile=0;profile<16;profile++){
            CanopyPlacementLegacyOracle.World world=new CanopyPlacementLegacyOracle.World();world.time=1;world.setBlockState(ROOT,block.getDefaultState().withProperty(BlockCanopy.FACING,EnumFacing.NORTH),2);TileEntityCanopy root=TileEntityCanopy.at(world,ROOT);NBTTagCompound tag=new NBTTagCompound();tag.setInteger("x",ROOT.getX());tag.setInteger("y",ROOT.getY());tag.setInteger("z",ROOT.getZ());tag.setLong("Anchor",ROOT.toLong());tag.setInteger("CanopyMount",profile%4);tag.setInteger("CanopyMotion",profile/4%2);tag.setInteger("CanopyHinge",profile%4);tag.setBoolean("CanopyOpenable",(profile&1)!=0);tag.setBoolean("CanopySlideForward",(profile&2)!=0);tag.setInteger("CanopyDepth",new int[]{0,17,80}[profile%3]);tag.setInteger("CanopyScale",new int[]{10,71,100}[profile%3]);tag.setInteger("CanopyAngle",profile%(block.length==3?4:3));tag.setBoolean("CenteredPlacement",true);if(block.opening()){tag.setLong("Pair",ROOT.toLong());tag.setInteger("CanopyWidth",new int[]{1,3,9}[profile%3]);}root.readFromNBT(tag);List<CanopyMesh.Face> faces=root.baseFaces();NBTTagCompound settings=new NBTTagCompound();root.large.write(settings);JsonObject input=new JsonObject();input.addProperty("id",block.kind);input.addProperty("profile",profile);JsonArray sourceFaces=new JsonArray();for(CanopyMesh.Face face:faces){JsonObject value=new JsonObject();value.addProperty("group",face.group);JsonArray points=new JsonArray();for(Vec3d vertex:face.vertices)for(double coordinate:new double[]{vertex.x,vertex.y,vertex.z})points.add(Long.toString(Double.doubleToRawLongBits(coordinate)));value.add("points",points);sourceFaces.add(value);}input.add("faces",sourceFaces);inputs.println(gson.toJson(input));
            for(EnumFacing facing:EnumFacing.HORIZONTALS)for(double[] interval:INTERVALS){JsonObject row=new JsonObject();row.addProperty("id",block.kind);row.addProperty("profile",profile);row.addProperty("width",root.width());row.addProperty("mask",root.mask());row.addProperty("roof",block.kind.equals("regular_canopy_glass")?root.roofMask():root.mask());row.addProperty("centered",root.centeredPlacement);row.addProperty("facing",facing.getIndex());row.addProperty("from",interval[0]);row.addProperty("to",interval[1]);row.add("settings",CanopySettingsLegacyOracle.tags(settings));JsonArray bounds=new JsonArray();for(CanopyMesh.Face face:faces){AxisAlignedBB local=CanopyPose.sweptBounds(face,block.kind,root.width(),root.large,interval[0],interval[1]);Vec3d a=CanopyMesh.rotate(new Vec3d(local.minX,local.minY,local.minZ),facing),b=CanopyMesh.rotate(new Vec3d(local.maxX,local.maxY,local.maxZ),facing);AxisAlignedBB box=new AxisAlignedBB(a.x,a.y,a.z,b.x,b.y,b.z).offset(ROOT);JsonArray values=new JsonArray();for(double v:new double[]{box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ})values.add(Long.toString(Double.doubleToRawLongBits(v)));bounds.add(values);boxes++;}row.add("boxes",bounds);out.println(gson.toJson(row));profiles++;}
        }}check(file,"a870f787b01c7521e492aa69f3e01231879c2eeaecb51cf213b1acc3538901a1");check(new File(file.getParentFile(),"canopy-sweep-inputs-forge.jsonl"),"9d77b066006e48f667ee700cb0124196b7bb2f2d956902afb75b526ee51c3b4a");System.out.println("Actual canopy sweep PASS profiles="+profiles+" boxes="+boxes+" file="+file);
    }
}
